{"command": "python3 - << 'EOF'
import re, glob, json
queries = ["Calma Remix","Ay Vamos","Criminal","Waka Waka","Bum Bum Tam Tam","Mayores","Chantaje","Felices los 4"]
files = sorted(glob.glob('/tmp/yt_*.json'), key=lambda f: int(re.search(r'yt_(\d+)', f).group(1)))
for q, f in zip(queries, files):
    html = open(f, encoding='utf-8', errors='ignore').read()
    pairs = re.findall(r'"videoRenderer":\{"videoId":"([A-Za-z0-9_-]{11})".*?"title":\{"runs":\[\{"text":"((?:[^"\\]|\\.)*?)"\}', html)
    seen = []
    for vid, title in pairs:
        if vid not in [v for v,_ in seen]:
            seen.append((vid, title))
    print(f"== {q} ==")
    for vid, title in seen[:6]:
        print('  ', vid, '|', title[:90])
EOF"}

